const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Point(-73.845369, -9.799994).buffer(5000);
    const date1 = '2017-08-23';
    const date2 = '2022-08-21';
    const scale = 30; // Scale appropriate for Landsat/Dynamic World

    // 2. Data Acquisition & Processing Function
    const getForestArea = function(dateStr) {
        const startDate = ee.Date(dateStr);
        const endDate = startDate.advance(1, 'day');

        // Use Dynamic World as the primary source for recent land cover
        let collection = ee.ImageCollection('GOOGLE/DYNAMICWORLD/V1')
            .filterBounds(aoi)
            .filterDate(startDate, endDate);

        let image = collection.mosaic().clip(aoi);
        // The 'label' band for trees is 1
        let forest = image.select('label').eq(1);

        let area = forest.multiply(ee.Image.pixelArea()).reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: aoi,
            scale: scale,
            maxPixels: 1e9
        });

        let pixelCount = forest.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: aoi,
            scale: scale,
            maxPixels: 1e9
        });

        return {
            collection: collection,
            area: area.get('label'),
            pixels: pixelCount.get('label')
        };
    };

    // 3. Calculation for each date
    const result2017 = getForestArea(date1);
    const result2022 = getForestArea(date2);

    const collectionSize2017 = result2017.collection.size().getInfo();
    const collectionSize2022 = result2022.collection.size().getInfo();

    // Check for empty collections
    if (collectionSize2017 === 0 || collectionSize2022 === 0) {
        console.log(`Image collection size 2017: ${collectionSize2017}`);
        console.log(`Image collection size 2022: ${collectionSize2022}`);
        console.log("No images found for one or both dates.");
        console.log("C1");
        return;
    }

    const area2017 = ee.Number(result2017.area).getInfo();
    const area2022 = ee.Number(result2022.area).getInfo();
    const pixels2017 = ee.Number(result2017.pixels).getInfo();
    const pixels2022 = ee.Number(result2022.pixels).getInfo();

    // 4. Validation & Final Answer
    console.log(`2017-08-23 Forest Area (km2): ${(area2017 / 1e6).toFixed(2)}`);
    console.log(`2017-08-23 Valid Pixels: ${pixels2017}`);
    console.log(`2022-08-21 Forest Area (km2): ${(area2022 / 1e6).toFixed(2)}`);
    console.log(`2022-08-21 Valid Pixels: ${pixels2022}`);

    if (area2017 === null || area2022 === null) {
        console.log("Calculation failed, result is null.");
        console.log("C3");
        return;
    }

    if (pixels2017 === 0 || pixels2022 === 0) {
        console.log("No valid pixels found after processing.");
        console.log("C2");
        return;
    }

    if (area2022 > area2017) {
        console.log("B");
    } else {
        console.log("A");
    }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error during Earth Engine initialization or analysis: ${e}`);
    console.log("D");
  }
}

initEE();
